/**
 * The learning surface's wire shapes, on `src/api/schema.d.ts` — generated by
 * `make types` from the real pydantic models (docs/adr/0157). The answer side
 * of a card is C8's `Card`, so everything the entity card renderer knows how
 * to show arrives here unchanged.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

export type DeckCard = Schemas['DeckCard']
export type LearningQueue = Schemas['LearningQueue']
export type ReviewResult = Schemas['ReviewResult']
export type LearningProgress = Schemas['LearningProgress']
export type SeriesDay = Schemas['SeriesDay']
export type TypeCoverage = Schemas['TypeCoverage']
export type OverviewCard = Schemas['OverviewCard']
export type LearningOverview = Schemas['LearningOverview']
export type LearningCounts = Schemas['LearningCounts']
export type LearningSettings = Schemas['LearningSettings']

export type LearnQuestion = Schemas['QuestionRow']
export type LearnQuestionPage = Schemas['QuestionPage']

/** Again / Hard / Good / Easy — the FSRS ratings, as the API takes them. */
export type Rating = 1 | 2 | 3 | 4

/**
 * A choice answer grades itself: picking right is a Good, picking wrong an
 * Again. One place, so the two choice-shaped formats cannot disagree.
 */
export function choiceRating(pickedCorrectly: boolean): Rating {
  return pickedCorrectly ? 3 : 1
}
